import{_ as s,I as t,o as r,c as d,b6 as e,j as h,J as i,w as o}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"스마트 여행 계획 Agent 플랫폼 개발 실전","description":"","frontmatter":{},"headers":[],"relativePath":"ko-kr/stage-2/assignments/travel-planning-agent-platform/index.md","filePath":"ko-kr/stage-2/assignments/travel-planning-agent-platform/index.md"}'),p={name:"ko-kr/stage-2/assignments/travel-planning-agent-platform/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),n=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=e('<h1 id="스마트-여행-계획-agent-플랫폼-개발-실전" tabindex="-1">스마트 여행 계획 Agent 플랫폼 개발 실전 <a class="header-anchor" href="#스마트-여행-계획-agent-플랫폼-개발-실전" aria-label="Permalink to “스마트 여행 계획 Agent 플랫폼 개발 실전”">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to “개요”">​</a></h2><p>이 실전 프로젝트에서는 실제 PRD를 바탕으로 스마트 여행 계획 Agent 플랫폼을 처음부터 완성하게 됩니다. 구조화된 입력을 받아 일별 일정을 생성하고, 저장 및 재사용이 가능한 완전한 AI 제품을 구축합니다. 단순한 챗봇이 아닌, 작업 관리 기능을 갖춘 제품을 만들게 됩니다.</p><p>이 프로젝트는 Stage 2의 종합 실전环节입니다. 핵심 과제는 AI가 조작할 수 없는 긴 텍스트가 아닌, 구조화되고 실용적인 일정 계획을 생성하도록 만드는 것입니다.</p><h2 id="사전-지식" tabindex="-1">사전 지식 <a class="header-anchor" href="#사전-지식" aria-label="Permalink to “사전 지식”">​</a></h2><p>이 프로젝트를 시작하기 전에 다음 내용을 이미 숙지하고 있어야 합니다:</p><ul><li>프론트엔드 페이지 디자인 및 컴포넌트 라이브러리 사용 (<a href="./../../frontend/ui-design/">UI 디자인</a>, <a href="./../../frontend/modern-component-library/">모던 컴포넌트 라이브러리</a>)</li><li>백엔드 API 설계 및 개발 (<a href="./../../backend/ai-interface-code/">API 코드 작성</a>)</li><li>데이터베이스 기초와 Supabase (<a href="./../../backend/database-supabase/">데이터베이스부터 Supabase까지</a>)</li><li>Git 워크플로우 및 배포 (<a href="./../../backend/git-workflow/">Git과 GitHub</a>, <a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포</a>)</li></ul><h2 id="학습-목표" tabindex="-1">학습 목표 <a class="header-anchor" href="#학습-목표" aria-label="Permalink to “학습 목표”">​</a></h2><p>이 실전을 완료하면 다음을 할 수 있게 됩니다:</p><ol><li>PRD를 읽고 Agent 플랫폼의 개발 작업 목록을 추출하기</li><li>구조화된 입력 양식과 구조화된 출력 형식 설계하기</li><li>사용자 입력, 모델 호출, 결과 저장을 처리하는 Agent 오케스트레이션 계층 구현하기</li><li>&quot;생성 → 저장 → 재사용&quot;의 비즈니스 루프 구축하기</li><li>엔드투엔드 연동 테스트를 완료하고 데모 가능한 AI 제품 프로토타입을 전달하기</li></ol><h2 id="프로젝트-소개" tabindex="-1">프로젝트 소개 <a class="header-anchor" href="#프로젝트-소개" aria-label="Permalink to “프로젝트 소개”">​</a></h2><p>구축할 제품은 스마트 여행 계획 Agent 플랫폼입니다:</p><table tabindex="0"><thead><tr><th>기능</th><th>설명</th></tr></thead><tbody><tr><td><strong>일정 계획</strong></td><td>사용자가 출발지, 목적지, 날짜, 예산, 취향을 입력하면 시스템이 일별 일정을 생성합니다</td></tr><tr><td><strong>예산 분할</strong></td><td>일정 결과에 예산 배분 및 제안이 포함됩니다</td></tr><tr><td><strong>기록 관리</strong></td><td>사용자가 과거 계획을 저장하고, 다시 생성하고, 내보낼 수 있습니다</td></tr><tr><td><strong>관리 대시보드</strong></td><td>관리자가 인기 목적지, 실패한 작업 및 사용자 피드백을 확인할 수 있습니다</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 입구</p><p>이 프로젝트의 요구사항 문서는 GitHub에 있습니다: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/ko-kr/stage-2/assignments/travel-planning-agent-platform/PRD.md" target="_blank" rel="noreferrer">PRD 보기</a></p></div>',14)),h("div",c,[i(n,null,{default:o(()=>[i(l,{active:0,items:[{title:"요구사항 분석",description:"PRD를 읽고 페이지, Agent 오케스트레이션, 입출력 구조를 명확히 합니다"},{title:"골격 구축",description:"AI로 홈페이지, 계획 페이지, 기록 페이지, 관리 페이지 골격을 생성합니다"},{title:"반복 개발",description:"모듈별로 구조화된 출력, 작업 상태, 기록 관리를 추가합니다"},{title:"연동 및 배포",description:"엔드투엔드로 실행하고, 배포하여 데모를 준비합니다"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="제1부-요구사항-분석" tabindex="-1">제1부: 요구사항 분석 <a class="header-anchor" href="#제1부-요구사항-분석" aria-label="Permalink to “제1부: 요구사항 분석”">​</a></h2><h3 id="_1-1-prd-읽기" tabindex="-1">1.1 PRD 읽기 <a class="header-anchor" href="#_1-1-prd-읽기" aria-label="Permalink to “1.1 PRD 읽기”">​</a></h3><p>PRD 문서를 열고 다음 질문에 중점적으로 답해보세요:</p><ul><li>첫 번째 버전은 단일 목적지만 지원하는가?</li><li>일정 출력은 반드시 구조화되어야 하는가? 구조는 무엇인가?</li><li>내보내기 기능은 어디까지 구현하는가? (공유 링크 / PDF / 이미지)</li><li>관리 대시보드 통계와 작업 로그의 범위는 무엇인가?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>위 질문들에 명확한 답이 없다면, 코드 작성을 시작하지 마세요. 요구사항 이해가 불충분한 것은 재작업의 가장 흔한 원인입니다.</p></div><h3 id="_1-2-시스템-아키텍처-확인" tabindex="-1">1.2 시스템 아키텍처 확인 <a class="header-anchor" href="#_1-2-시스템-아키텍처-확인" aria-label="Permalink to “1.2 시스템 아키텍처 확인”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; planner[&quot;계획 페이지&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  planner --&gt; agent[&quot;Agent 오케스트레이션 계층&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; model[&quot;모델 호출&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; db[&quot;데이터베이스&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; history[&quot;과거 계획&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; admin[&quot;관리 통계 및 로그&quot;]</span></span></code></pre></div><h2 id="제2부-프로젝트-골격-구축" tabindex="-1">제2부: 프로젝트 골격 구축 <a class="header-anchor" href="#제2부-프로젝트-골격-구축" aria-label="Permalink to “제2부: 프로젝트 골격 구축”">​</a></h2><h3 id="_2-1-프론트엔드-페이지-생성" tabindex="-1">2.1 프론트엔드 페이지 생성 <a class="header-anchor" href="#_2-1-프론트엔드-페이지-생성" aria-label="Permalink to “2.1 프론트엔드 페이지 생성”">​</a></h3><p>프롬프트 참고:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>현재 PRD를 바탕으로 스마트 여행 계획 Agent 플랫폼의 프론트엔드 골격을 생성해 주세요.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>요구사항:</span></span>
<span class="line"><span>1. 페이지 구성: 홈페이지, 계획 페이지, 일정 상세 페이지, 기록 페이지, 관리 페이지</span></span>
<span class="line"><span>2. 계획 페이지는 왼쪽에 양식, 오른쪽에 결과 미리보기</span></span>
<span class="line"><span>3. 먼저 페이지 구조와 가짜 데이터만 생성하고, 실제 API는 연결하지 않습니다</span></span>
<span class="line"><span>4. 모던 AI 제품 같은 스타일</span></span></code></pre></div><h3 id="_2-2-페이지-구조-확인" tabindex="-1">2.2 페이지 구조 확인 <a class="header-anchor" href="#_2-2-페이지-구조-확인" aria-label="Permalink to “2.2 페이지 구조 확인”">​</a></h3><p>항목별 확인:</p><ul><li>[ ] 계획 페이지의 양식 필드가 PRD와 일치하는가</li><li>[ ] 결과 미리보기 영역이 구조화된 일정 데이터를 표시할 수 있는가</li><li>[ ] 기록 페이지가 여러 계획을 표시할 수 있는가</li><li>[ ] 관리 대시보드 페이지가 통계 데이터를 표시할 수 있는가</li></ul><h2 id="제3부-반복-개발" tabindex="-1">제3부: 반복 개발 <a class="header-anchor" href="#제3부-반복-개발" aria-label="Permalink to “제3부: 반복 개발”">​</a></h2><h3 id="_3-1-모듈별-진행" tabindex="-1">3.1 모듈별 진행 <a class="header-anchor" href="#_3-1-모듈별-진행" aria-label="Permalink to “3.1 모듈별 진행”">​</a></h3><ol><li><strong>인증</strong>: 회원가입, 로그인</li><li><strong>계획 양식</strong>: 구조화된 입력 (출발지, 목적지, 날짜, 예산, 취향)</li><li><strong>Agent 오케스트레이션</strong>: 입력 수신 → 모델 호출 → 구조화된 출력 파싱</li><li><strong>결과 표시</strong>: 일정을 일별로 표시, 예산 분할, 제안</li><li><strong>기록 관리</strong>: 계획 저장, 재생성, 내보내기</li><li><strong>관리 대시보드</strong>: 인기 목적지, 실패한 작업, 사용자 피드백</li><li><strong>작업 상태</strong>: 생성 중 / 성공 / 실패 상태 관리 및 오류 기록</li></ol><h3 id="_3-2-모듈-자체-점검" tabindex="-1">3.2 모듈 자체 점검 <a class="header-anchor" href="#_3-2-모듈-자체-점검" aria-label="Permalink to “3.2 모듈 자체 점검”">​</a></h3><table tabindex="0"><thead><tr><th>점검 항목</th><th>검증 방법</th></tr></thead><tbody><tr><td>입력 완전성</td><td>양식 필드가 PRD와 일치하는가</td></tr><tr><td>출력 구조화</td><td>일정 결과가 구조화된 데이터인가 (긴 텍스트가 아닌)</td></tr><tr><td>데이터 일관성</td><td>trip, itinerary, logs 데이터가 서로 일치하는가</td></tr><tr><td>루프 검증</td><td>&quot;입력 → 생성 → 저장 → 재생성&quot;을 데모할 수 있는가</td></tr></tbody></table><h2 id="제4부-연동-및-배포" tabindex="-1">제4부: 연동 및 배포 <a class="header-anchor" href="#제4부-연동-및-배포" aria-label="Permalink to “제4부: 연동 및 배포”">​</a></h2><h3 id="_4-1-엔드투엔드-테스트" tabindex="-1">4.1 엔드투엔드 테스트 <a class="header-anchor" href="#_4-1-엔드투엔드-테스트" aria-label="Permalink to “4.1 엔드투엔드 테스트”">​</a></h3><p>최소한 다음 시나리오를 검증하세요:</p><ul><li>일정 파라미터 입력 → 일별 일정 생성 → 예산 분할 확인 → 기록에 저장</li><li>기록에서 일정 재생성</li><li>관리자가 작업 통계와 실패 로그 확인</li></ul><h2 id="산출물" tabindex="-1">산출물 <a class="header-anchor" href="#산출물" aria-label="Permalink to “산출물”">​</a></h2><p>이 프로젝트를 완료한 후 다음을 제출해야 합니다:</p><ul><li>[ ] 접근 가능한 온라인 데모 링크</li><li>[ ] 소스 코드 저장소 링크 (README 포함)</li><li>[ ] PRD 문서</li><li>[ ] 핵심 페이지 스크린샷 (계획 페이지, 일정 상세 페이지, 기록 페이지, 관리 대시보드)</li><li>[ ] 60초 데모 영상</li></ul><h2 id="평가-기준" tabindex="-1">평가 기준 <a class="header-anchor" href="#평가-기준" aria-label="Permalink to “평가 기준”">​</a></h2><table tabindex="0"><thead><tr><th>영역</th><th>기본 요구사항</th><th>심화 요구사항</th></tr></thead><tbody><tr><td>PRD 정합성</td><td>페이지, 기능, 데이터 구조가 기본적으로 PRD에 부합</td><td>설계 결정을 명확히 설명할 수 있음</td></tr><tr><td>제품 루프</td><td>계획 → 저장 → 기록 → 재생성이 실행 가능</td><td>내보내기 및 공유 지원</td></tr><tr><td>출력 품질</td><td>일정 결과가 구조화되고 가독성이 높음</td><td>예산 분할이 합리적이고 제안이 타겟팅됨</td></tr><tr><td>관리 기능</td><td>작업 통계와 실패 로그를 확인할 수 있음</td><td>인기 목적지 분석이 있음</td></tr><tr><td>엔지니어링 완성도</td><td>프론트엔드, 백엔드, 데이터베이스, 모델 호출 체인이 연결됨</td><td>작업 상태 관리가 완비되고 오류 추적 가능</td></tr></tbody></table><h2 id="참고-자료" tabindex="-1">참고 자료 <a class="header-anchor" href="#참고-자료" aria-label="Permalink to “참고 자료”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 디자인</a></li><li><a href="./../../frontend/modern-component-library/">모던 컴포넌트 라이브러리로 인터페이스 업데이트하기</a></li><li><a href="./../../backend/database-supabase/">데이터베이스부터 Supabase까지</a></li><li><a href="./../../backend/ai-interface-code/">대형 언어 모델로 API 코드 및 문서 작성하기</a></li><li><a href="./../../backend/git-workflow/">Git 및 GitHub 워크플로우</a></li><li><a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포 방법</a></li></ul>`,30))])}const x=s(p,[["render",b]]);export{P as __pageData,x as default};
